const steps=rows=>rows.map(([title,body])=>({title,body})),parts=rows=>rows.map(([name,role])=>({name,role}));
const exp=(title,instruction,observe,values)=>({title,instruction,observe,values});
const quiz=(question,options,answer,explanation)=>({question,options,answer,explanation});
export const utilityLessons={
 'Faucet':{
 simple:'Turning a screw lifts a washer off its seat, and the pressure already in the pipe does the rest.',
 overview:'A compression tap is four pieces of physics in one small object. A thread turns rotation into a lift of exactly 1.5 mm per turn. The lift opens a curtain between washer and seat, which is what the water actually squeezes through, and which stops mattering once it is wider than the 12 mm bore behind it. The tap and the whole run of pipe behind it then resist together, both as the square of the flow, so the flow comes out as the square root of the pressure. And when the handle is shut, the moving column of water in the pipe has to be brought to rest: do that too quickly and the pressure it takes is many times the supply.',
 steps:steps([
  ['Turn the handle','A 1.5 mm pitch thread raises the washer 1.5 mm for every full turn. How hard the handle is gripped changes nothing; only the turns count.'],
  ['Open a curtain, not a hole','What the water passes through is the cylindrical gap between the washer rim and the seat: 12 mm around, and as tall as the lift. A quarter turn opens 14 mm² of it.'],
  ['Meet the bore','By about two thirds of a turn that curtain is wider than the 113 mm² seat bore, and from there the bore is the limit. Opening further adds almost nothing, which is why a tap feels like it does all its work in the first turn.'],
  ['Share the pressure with the pipe','The seat and the pipework behind it both resist as the square of the flow. Wide open, most of the supply pressure is being spent in the pipe rather than in the tap.'],
  ['Stop the water','Shutting the handle has to stop everything moving behind it. The faster it is shut, the higher the pressure that takes, and the bang in the wall is that pressure arriving.'],
 ]),
 parts:parts([
  ['Threaded spindle','Turns rotation into a lift of 1.5 mm a turn, and holds it there.'],
  ['Washer','A rubber disc that seals against the seat, and wears.'],
  ['Valve seat','A flat ring of 12 mm bore; the fixed half of the seal and the upper limit on the opening.'],
  ['Tap body and waterway','Carries the supply up the middle, round the seat and out along the spout.'],
  ['Aerator','Mixes air into the stream so the same flow feels fuller, at the cost of a little more resistance.'],
  ['The pipe behind it','Twenty metres of run, bends and a stop valve, which is where most of the pressure goes once the tap is open.'],
 ]),
 tryIt:[
  exp('Open it a quarter turn','Leave the pressure at 2 bar and set a quarter turn, then press Fill the bucket.','Only 0.38 mm of lift and 14 mm² of opening, and already more than half the flow the tap will ever give.',{turns:.25,pressure:2,washer:0,aerator:1,closing:1}),
  exp('Open it all the way','Set four turns and fill the bucket again.','Sixteen times the lift and the flow barely moves: the seat bore took over long ago, and the pipe is taking most of the pressure.',{turns:4,pressure:2,washer:0,aerator:1,closing:1}),
  exp('Turn the supply up','Keep it wide open and raise the pressure from 2 bar to 6.','Three times the pressure gives about 1.73 times the flow, which is the square root of three. Flow follows the root of pressure, not the pressure.',{turns:4,pressure:6,washer:0,aerator:1,closing:1}),
  exp('Shut it fast','Put the pressure back to 2 bar and set the closing time to 0.05 s.','Fifteen bar of surge, against a supply of two. Stopping moving water quickly costs far more pressure than moving it did.',{turns:4,pressure:2,washer:0,aerator:1,closing:.05}),
  exp('Let the washer perish','Set the washer to perished and leave the handle shut.','The handle is hard closed and the tap is still passing about five millilitres a minute, which is a drip every half second and a ten litre bucket every thirty two hours.',{turns:0,pressure:2,washer:2,aerator:1,closing:1}),
 ],
 deeper:[
  {title:'Why the first turn does nearly everything',body:'The opening is a curtain of circumference 38 mm and height equal to the lift, so it grows in proportion to the turns. The bore behind it does not grow at all. They are equal when the lift is a quarter of the bore diameter, that is 3 mm, or two turns. After that, turning the handle changes the drawing and not the flow. A tap that has to be opened four turns to run properly has something wrong downstream of the seat, not at it.'},
  {title:'Why doubling the pressure does not double the flow',body:'Every resistance here is turbulent: the pressure it costs goes as the square of the flow through it. Add them up and the supply pressure equals a constant times the flow squared, so the flow is the square root of the pressure over that constant. Four times the pressure for twice the flow is the standing bargain of plumbing, and it is why a mains booster buys less than people expect.'},
  {title:'Where the pressure actually goes',body:'With the tap shut, the full supply pressure stands at the seat. Open it wide and the seat is no longer the narrowest thing in the system: at 2 bar most of the drop has moved into the pipe run. This is why one tap runs slower when another is opened, and why the tap itself is rarely the thing worth replacing.'},
  {title:'The bang in the wall',body:'Joukowsky put it simply: the pressure needed to stop flowing water is its density times the speed of sound in the pipe times the speed lost. Water moving two metres a second in copper needs about 24 bar to be stopped instantly. What saves the pipework is time: the wave runs to the far end and back in about 33 ms here, and a closure slower than that is relieved in proportion. A lever tap that shuts in a tenth of a turn is the one that knocks.'},
 ],
 misconception:'The handle does not push the water; it only changes a restriction in a system that is already under pressure. It is also not a proportional control: over most of its travel it is doing nothing at all, because the seat bore, and then the pipe, took over as the limit.',
 limits:'A compression tap with a 1.5 mm thread pitch, a 12 mm seat bore and a discharge coefficient of 0.62. Everything behind the tap is one fixed loss coefficient of 200 on 15 mm pipe, standing for about 20 m of run with its bends and stop valve. Flow is steady and incompressible; the surge uses the Joukowsky bound relieved by the pipe period. Temperature, dissolved air, cavitation at the seat, pipe flexing and any surge arrestor are all left out.',
 sources:[
  {title:'OpenStax: Bernoulli flow applications',url:'https://openstax.org/books/college-physics-2e/pages/12-3-the-most-general-applications-of-bernoullis-equation'},
  {title:'Water hammer and the Joukowsky equation',url:'https://www.engineeringtoolbox.com/water-hammer-d_1091.html'},
 ],
 quiz:quiz('A tap is open one full turn and runs at 12.5 litres a minute. You open it three turns further. What happens?',['Almost nothing: the seat bore, and then the pipe, are already the limit.','The flow roughly quadruples, because the lift has quadrupled.','The flow doubles, because the opening area doubles.'],0,'The curtain under the washer passed the seat bore at about two thirds of a turn. Beyond that the opening is fixed at 113 mm², and the extra turns change the picture without changing the flow.'),
 },

 'Toilet tank':{
 simple:'One lift of the handle primes a siphon, and then the whole charge goes on its own until air breaks it.',
 overview:'A siphon cistern is the flush that cannot leak. Lifting the disk throws a slug of water over the crest of the bell and fills the falling leg; from that moment the tank is connected to the outlet by a solid column of water, and it empties at whatever rate the head allows. It stops not when the water runs out but when the falling level reaches the bottom lip of the bell and lets air in, which parts the column at once. There is no valve holding anything, so there is no partly open state to sit in and nothing to weep into the bowl between flushes. How much water each flush uses is not the size of the tank but the distance from the set level down to that lip.',
 steps:steps([
  ['Prime it','The disk lifts and throws water over the crest into the falling leg. Under about twenty millimetres of stroke it throws nothing over and the handle does nothing at all.'],
  ['The column takes over','Now the surface of the tank is connected to the outlet by a full pipe. The head is the height of the surface above that outlet, and the speed is the square root of twice gravity times it.'],
  ['It slows as it goes','Every litre that leaves lowers the surface, which lowers the head, which lowers the speed. The flush is fastest in its first instant and never that fast again.'],
  ['Air breaks it','The level reaches the bottom lip of the bell, air gets under, and the column parts. The flow does not tail off; it stops.'],
  ['The float refills it','The valve is wide open at first and closes in proportion over the last few centimetres, so the refill fades into the set level rather than slamming shut.'],
 ]),
 parts:parts([
  ['Cistern','Its plan area turns a level into a volume.'],
  ['Bell','Encloses the rising leg; its bottom lip ends the flush.'],
  ['Air-break lip','Twelve millimetres above the floor, and the whole of the timing.'],
  ['Outlet standpipe','The falling leg; how far it drops sets the head.'],
  ['Priming disk','One stroke, once, to start the column.'],
  ['Float valve','Reads the level and closes in proportion as it rises.'],
 ]),
 tryIt:[
  exp('One ordinary flush','Leave everything as it opens and press Flush it.','About six litres away in under five seconds, fastest at the start, then stopping dead at the lip. The refill takes half a minute or more.',{level:.12,bore:.032,pressure:2,stroke:.025,perDay:5}),
  exp('Set the float too high','Raise the fill level to 260 mm and flush again.','Nearly fourteen litres instead of six, and every flush from now on. The extra head also makes it faster, which is the wrong kind of better.',{level:.26,bore:.032,pressure:2,stroke:.025,perDay:5}),
  exp('Widen the siphon','Put the level back to 120 mm and open the bore to 45 mm.','Twice as fast and exactly the same six litres. The bore sets how quickly the charge goes and not how much of it goes.',{level:.12,bore:.045,pressure:2,stroke:.025,perDay:5}),
  exp('Turn up the supply','Leave the flush alone and raise the pressure from 2 bar to 5.','The flush is identical to the litre and the second. Only the refill is quicker, because pressure is on the wrong side of the siphon to matter.',{level:.12,bore:.032,pressure:5,stroke:.025,perDay:5}),
  exp('Half-hearted on the handle','Set the priming stroke to 10 mm and press Flush it.','The disk lifts, the water falls back, and nothing happens. A siphon is all or nothing, and priming it is the all.',{level:.12,bore:.032,pressure:2,stroke:.01,perDay:5}),
 ],
 deeper:[
  {title:'Why a siphon cistern cannot drip into the bowl',body:'There is no seal between tank and bowl to fail. A flapper valve cistern holds its charge behind a rubber flap that has to seat perfectly every time, and a flap that does not is a silent leak of several litres an hour. A siphon has no such part: between flushes the leg is full of air, and air does not siphon. This is why siphons were required in some countries for decades, and why the water lost to running cisterns rose sharply when that requirement was relaxed.'},
  {title:'Why the flush is not a straight line',body:'The discharge is the square root of the head, and the head is falling throughout. Start at 120 mm above a floor whose outlet is 250 mm lower and the head runs from 370 mm down to 262 mm, so the speed falls by about fifteen percent across the flush. Start the float at 260 mm and the head runs from 510 mm, which is why a higher setting is not only more water but faster water.'},
  {title:'Bore and level do different jobs',body:'The bore sets the rate and the level sets the amount. That is a clean separation and it is worth holding on to: a flush that is too weak wants a wider leg, a flush that uses too much wants a lower float, and the two adjustments do not interfere. What a wider bore does cost is a shorter, fiercer flush, which is not always what the bowl wants.'},
  {title:'Where the litres actually go',body:'Six litres a flush, five flushes a day, is about eleven cubic metres a year for one person. Ten millimetres of extra float setting is 0.55 litres a flush, which is a cubic metre a year, for nothing. This is the ordinary way household water is lost: not in a dramatic leak, but in a setting nobody ever looked at.'},
 ],
 misconception:'The handle does not push the water out; it only starts the siphon. After the first half second it makes no difference whether the handle is held, released or let go, and holding it down neither lengthens the flush nor uses more water. What sets the volume is where the float was set, months ago.',
 limits:'The cistern only: the bowl, its trap and the swirl are all absent. A 0.055 square metre tank with its outlet 250 mm below the floor and the bell lip 12 mm above it, a discharge coefficient of 0.7, and a float valve that passes 0.08 litres a second at one bar and closes over the last 30 mm. Friction inside the bell and the hydraulics of the priming stroke itself are not modeled; priming is treated as a threshold on the stroke. Flapper valve cisterns, which do have a part that can be held open, are discussed but not simulated.',
 sources:[
  {title:'Torricelli\'s law and efflux from a tank',url:'https://openstax.org/books/university-physics-volume-1/pages/14-6-bernoullis-equation'},
  {title:'Toilet leaks and household water use',url:'https://www.epa.gov/watersense/fix-leak-week'},
 ],
 quiz:quiz('You widen the siphon bore from 32 mm to 45 mm and change nothing else. What happens to the water each flush uses?',['Nothing: it is set by the fall from the water level to the air-break lip.','It roughly doubles, because the leg is twice the area.','It falls, because the flush is over sooner.'],0,'The bore sets the rate and the geometry sets the amount. The siphon runs until the level reaches the lip whatever the bore is, so the same fall over the same plan area gives the same litres; it simply gets there in half the time.'),
 },

 'Water meter':{
 simple:'Water turns a small turbine, the turbine turns a counter, and the counter is what the bill is read from.',
 overview:'A meter is a turbine and a gearbox: every litre that passes turns the impeller the same number of times, and a train of gears trades that speed for a register that moves slowly enough to read. What makes a meter worth studying is where that proportionality breaks down. Below a starting flow the water cannot overcome the friction in the bearings and the train, and the impeller does not move at all. Above it, and up to the minimum flow the meter is specified at, it turns but registers less than passes. The standard, EN ISO 4064, bounds the error only above that minimum. This is why a tap dripping once a second can run for a year without the register moving, and why the almost frictionless star wheel on the face is the only honest way to find out whether anything is flowing.',
 steps:steps([
  ['Water drives the impeller','Jets are directed at blades round the rim of the measuring chamber. The impeller is the only moving part the water touches.'],
  ['The gear train slows it down','Ten turns to a litre would spin a dial far too fast to read. The train trades that speed for the slow movement of the register, at a fixed ratio.'],
  ['The register counts up','It only ever increases. A bill is the difference between two readings, so an error at either end is an error in the bill.'],
  ['Small flows are lost','Below about half the minimum flow, the torque the water makes cannot start the impeller. Between there and Q1 the meter turns but under-reads, by as much as it likes.'],
  ['The star wheel still moves','Almost nothing is geared to it and almost nothing rubs, so it turns on any flow at all. Shut every tap and watch it: if it is moving, water is going somewhere.'],
 ]),
 parts:parts([
  ['Measuring chamber','Directs jets at the impeller blades.'],
  ['Impeller','Turns a fixed number of times for every litre, once it can turn at all.'],
  ['Reduction train','Trades impeller speed for readable register movement.'],
  ['Register','Counts cubic metres; the figure the bill uses.'],
  ['Sweep needle','One turn to a litre, for timing a flow by eye.'],
  ['Star wheel','Nearly frictionless, so it moves on flows the register cannot see.'],
 ]),
 tryIt:[
  exp('A shower for half an hour','Leave the meter and tariff as they are, set 9 litres a minute and half an hour, and run the water.','About 270 litres delivered and 265 registered: two percent lost, which is all the standard allows up here.',{flow:9,hours:.5,size:0,leak:0,tariff:2.4}),
  exp('Shut every tap and leave one dripping','Set the house flow to zero, add a leak of 0.005 litres a minute, and run it for a full day.','Seven litres go through the meter and the register does not move once. The star wheel turns the whole time.',{flow:0,hours:24,size:0,leak:.005,tariff:2.4}),
  exp('Make the leak worse','Raise the leak to 0.3 litres a minute and run another day.','Now the impeller turns, but it is in the band below Q1: the register admits to about half of what actually passed.',{flow:0,hours:24,size:0,leak:.3,tariff:2.4}),
  exp('Fit the larger meter','Keep the same 0.3 litre leak and change to the 4 m³/h meter.','The same leak is now below the starting flow. A meter sized for more water is blinder to small flows, because Q1 is its permanent flow divided by its ratio.',{flow:0,hours:24,size:1,leak:.3,tariff:2.4}),
  exp('Open everything at once','Set 30 litres a minute on the smaller meter and run it for a quarter of an hour.','Accurate to two percent, and now costing a third of a bar of pressure: the drop rises as the square of the flow.',{flow:30,hours:.25,size:0,leak:0,tariff:2.4}),
 ],
 deeper:[
  {title:'What Q1, Q2 and Q3 actually mean',body:'A meter is described by its permanent flow Q3 and a ratio R. Everything else follows: Q1, the minimum flow, is Q3 divided by R, and Q2 is 1.6 times Q1. Between Q1 and Q2 the meter may be five percent out; above Q2, two percent. Below Q1 the standard says nothing, which is not an oversight: it is an admission that nobody can hold a turbine to account down there.'},
  {title:'Why the error is always negative',body:'Friction only ever opposes the turning, so a turbine meter reads low, never high. That suits the customer at the margin and the supplier not at all, which is why the classes are written as they are and why a supplier replaces meters that have slowed with age.'},
  {title:'A bigger meter is a blinder meter',body:'Sizing a meter for the largest flow a building might draw pushes Q1 up with it, and everything below the new Q1 becomes invisible. An over-sized meter on a house with a small constant leak is a meter that will never report the leak. This is the reason meters are sized to the expected load rather than to the pipe.'},
  {title:'What the pressure costs',body:'The meter is a restriction like any other, so the pressure it takes goes as the square of the flow through it. The standard caps that at 0.63 bar at the permanent flow, which is why a meter that would be accurate at very small flows, with a tighter chamber, is not fitted: it would take too much pressure at the flows people actually use.'},
 ],
 misconception:'A water meter measures the water that passes. It measures the water that passes quickly enough to be noticed. Under the starting flow it measures nothing at all, and a slow leak is exactly the kind of flow it is worst at, which is the opposite of what would be most useful.',
 limits:'Bands and their limits follow EN ISO 4064, but the error inside each band is taken at the bottom edge rather than wandering across it as a real curve does, and below Q1 it is taken as a straight line down to nothing at the starting flow, which is set at half of Q1. The impeller is taken as ten turns to the litre and the run is watched at a thousand times life so that a day of leaking does not take a day. Temperature, air in the line, wear and the difference between single jet and multi jet chambers are all left out.',
 sources:[
  {title:'ISO 4064-1: water meters, metrological requirements',url:'https://www.iso.org/standard/55371.html'},
  {title:'Household leaks and how to find them',url:'https://www.epa.gov/watersense/fix-leak-week'},
 ],
 quiz:quiz('Every tap in the house is shut. The register has not moved in a week, but the small star wheel on the face is turning steadily. What does that mean?',['Water is flowing, too slowly for the register to record it.','Nothing: the star wheel turns on its own.','The meter is broken and should be replaced.'],0,'The star wheel is geared to almost nothing and rubs on almost nothing, so it moves on any flow at all. The register needs enough flow to overcome the friction of the whole train, and a slow leak does not supply it. A turning star wheel with the house shut is the classic sign of a leak.'),
 },

 'Sewing machine':{
 simple:'The needle carries one thread through the cloth, and a hook loops it around a second thread below.',
 overview:'A lockstitch machine coordinates the needle, rotary hook, thread take-up, and fabric feed. As the needle starts to rise from its lowest point, a small upper-thread loop forms. The hook catches it and carries it around the bobbin. The take-up then tightens the interlock while the feed mechanism prepares the next stitch.',
 steps:steps([['Carry the upper thread down','The needle eye, close to the point, takes thread through the fabric.'],['Catch the rising-needle loop','As the needle begins to rise, slack forms a loop that the hook point can enter.'],['Pass around the bobbin','The hook carries the upper-thread loop around the bobbin-thread supply.'],['Tighten the interlock','The take-up lever removes excess upper-thread slack and draws the crossing into the fabric.'],['Advance the cloth','The feed dogs rise, move the cloth, drop, and return while the needle is clear.']]),
 parts:parts([['Needle and eye','Carry the upper thread through the fabric.'],['Rotary hook','Catches and enlarges the loop.'],['Bobbin','Supplies lower thread.'],['Take-up lever','Pays out and recovers upper-thread slack.'],['Presser foot','Holds fabric against the feed mechanism.'],['Feed dogs','Advance fabric between penetrations.']]),
 tryIt:[exp('Sew a straight seam','Choose the straight template, lower the foot, then press Sew the template.','Red stitches remain on top of the cloth and blue thread remains below. The machine stops after 40 mm.',{template:0,foot:1,threaded:1,length:3}),exp('Make longer stitches','Start with fresh fabric, set 5 mm, then sew the same template.','Each feed stroke is longer and fewer stitches cover the same 40 mm.',{length:5}),exp('Sew around a corner','Choose the pocket-corner template and press Sew the template.','A simulated operator turns the cloth at needle-up. The machine continues the same straight stitch along the second edge.',{template:1,foot:1,threaded:1}),exp('Remove the lower thread','Select Bobbin thread missing and make one stitch.','The needle and feed still move, but no lockstitch joins the fabric.',{threaded:0}),exp('Lift the foot','Select Foot up, then try to sew.','The exercise waits for the foot to be lowered before feeding fabric.',{foot:0})],
 deeper:[{title:'Lockstitch',body:'The stitch uses two threads. The upper thread passes around the bobbin supply, creating an interlock with the lower thread. Proper tension places the crossing within the fabric thickness. The two threads are not tied into a separate hand-style knot at every penetration.'},{title:'Feed-dog lift and advance linkages',body:'Two coordinated motions give the feed dogs their four-stage path. Vertical motion decides when they contact the cloth; horizontal motion advances it during contact and returns below the plate. Stitch-length adjustment changes the horizontal excursion.'},{title:'Rotary shuttle and sewing hook',body:'Historical shuttle systems pass the lower-thread carrier through the upper loop. A rotary hook instead carries the loop around the bobbin case. The broad goal is the same, but their trajectories and timing mechanisms differ.'},{title:'Thread take-up lever',body:'The hook needs extra upper thread to make a large loop. The take-up first permits that slack, then recovers it to tighten the stitch. Timing and tension work together; simply pulling the thread tight throughout the cycle would prevent loop formation.'}],
 misconception:'The needle alone does not tie the stitch. The hook, lower thread, take-up, and feed must work in the correct sequence.',
 limits:'A teaching model of a straight lockstitch machine. The needle and take-up use fixed-length linkages. Shaped feed cams and a slotted regulator demonstrate coordinated lift and travel. Starting thread tails are held at the marked start. Hook and feed timing, thread-loop shape, and cloth guidance are prescribed; forces, thread tension, collisions and fabric deformation are not solved. Internal spaces and thread thickness are enlarged. The corner template includes simulated operator guidance, not automatic embroidery. The foot-up pause is an exercise interlock.',
 sources:[{title:'JUKI DDL-8700 manual: threading, hook relationship and feed timing',url:'https://www.juki.co.jp/industrial_j/download_j/manual_j/ddl8700/menu/ddl8700/pdf/instruction_eg.pdf'},{title:'SINGER: presser foot, feed and thread troubleshooting',url:'https://help.singer.com/en-US/troubleshooting-tips-389058'}],quiz:quiz('When should the feed dogs advance the cloth?',['While the needle is clear of the cloth.','While the needle is fixed through the cloth.','Only after removing the bobbin.'],0,'Feeding while the needle is embedded would bend the needle or damage the material.')},
};

utilityLessons['Door closer']={
 simple:'A spring closes the door while a hydraulic restriction controls how quickly it moves.',
 overview:'Opening the door stores elastic energy. After release, spring torque drives the hinge back toward closure. A hydraulic piston pushes oil through a restriction, dissipating energy. The enlarged section represents a hinge-driven pinion and rack; it does not claim to reproduce every closer linkage.',
 steps:[{title:'Store energy',body:'Opening rotates the hinge and loads the return spring.'},{title:'Release the door',body:'The spring supplies closing torque.'},{title:'Restrict oil flow',body:'A piston forces oil through a restriction; resistance limits speed and turns mechanical energy into thermal energy.'}],
 parts:[{name:'Door and hinge',role:'Constrain the swinging motion.'},{name:'Return spring',role:'Supplies closing torque.'},{name:'Pinion and rack',role:'Connect rotation to piston displacement.'},{name:'Hydraulic piston and restriction',role:'Resist motion and dissipate energy.'}],
 tryIt:[{title:'Let the door close',instruction:'Advance time after release.',observe:'The door angle and stored spring energy fall.',values:{seconds:3}},{title:'Increase damping',instruction:'Compare damping values 2 and 4 at the same elapsed time.',observe:'Larger damping leaves the door farther open.',values:{seconds:3,damping:4}},{title:'Increase spring stiffness',instruction:'Keep the damping and raise stiffness to 3.',observe:'The first-order model closes faster.',values:{stiffness:3}}],
 deeper:[{title:'An explicitly overdamped approximation',body:'Neglecting door inertia gives cθ̇ + kθ = 0, with solution θ = θ₀ exp(−kt/c). Spring energy is ½kθ². The decrease in that energy equals the integral of cθ̇² over time.'},{title:'Real closer behavior',body:'Real devices may use linkages, separate sweep and latch adjustments, backcheck, nonlinear spring torque, and temperature-dependent oil viscosity. The equation here isolates spring and damping effects.'}],
 misconception:'The hydraulic restriction does not supply closing energy; the spring does.',
 limits:'Linear rotational spring and viscous damping with inertia neglected. The door approaches zero angle asymptotically; latching, friction, wind, and contact with stops are not modeled. Piston travel uses a 40 mm reference pitch radius, with enlarged geometry.',
 sources:[{title:'OpenStax: damped harmonic motion',url:'https://openstax.org/books/university-physics-volume-1/pages/15-5-damped-harmonic-motion'}],
 quiz:{question:'Increasing damping at fixed spring stiffness makes this released door…',options:['Close more slowly.','Store energy in the oil pump.','Accelerate without resistance.'],answer:0,explanation:'The time constant is c/k, so more damping lengthens the closing process.'}
};
utilityLessons['Washing machine']={
 simple:'A drum lifts and tumbles the load, then spins it rapidly while a pump removes separated water.',
 overview:'A front-loading machine holds a perforated drum inside a nonrotating water tub. At wash and rinse speeds, lifters carry clothing upward and it falls through the water. During spin, larger inward acceleration keeps the load near the drum wall while water passes through the holes into the tub and drain. Springs and dampers support the tub assembly.',
 steps:[{title:'Wash or rinse',body:'Low-speed rotation repeatedly carries material upward and lets it fall. Wash uses detergent; rinse removes dissolved detergent and suspended soil.'},{title:'Drain',body:'The drain pump removes collected water from the outer tub.'},{title:'Spin',body:'Rapid rotation holds the load near the wall and helps separate water through the perforations.'},{title:'Limit vibration',body:'Suspension, damping, and load distribution reduce the motion transmitted to the cabinet.'}],
 parts:[{name:'Perforated drum',role:'Rotates the load while allowing water to pass.'},{name:'Lifters',role:'Carry material upward at low speed.'},{name:'Outer tub',role:'Contains water around the drum.'},{name:'Direct-drive motor',role:'Turns the drum in this chosen design.'},{name:'Drain pump and filter',role:'Remove collected water.'},{name:'Suspension and counterweight',role:'Support the tub assembly and affect vibration.'},{name:'Heater',role:'Adds energy in a heated wash; its separate linked experiment explains resistance heating.'}],
 tryIt:[{title:'Watch tumbling',instruction:'Select Wash with 40 rpm.',observe:'Markers rise with a lifter and then follow a falling arc.',values:{stage:0,washRpm:40}},{title:'Drain the tub',instruction:'Select Drain.',observe:'The wash-water pool disappears, the drum stops, and the drain-pump impeller turns.',values:{stage:2}},{title:'Spin an unbalanced load',instruction:'Select Spin at 800 rpm with 0.2 kg unbalanced mass.',observe:'The load stays near the rim and the tub vibrates; the readout gives a chosen steady-state vibration estimate.',values:{stage:3,spinRpm:800,imbalance:.2}}],
 deeper:[{title:'Why the low-speed markers fall',body:'For a marker carried at angular speed ω on radius R, the required wall force is m(ω²R + g cosθ), with θ measured from the bottom. In this idealization it loses contact when that force reaches zero. Its subsequent free-flight position follows constant horizontal velocity and vertical gravitational acceleration until it meets the drum again.'},{title:'A simplified vibration calculation',body:'An unbalanced mass produces a force amplitude mᵤRω². For supported mass M, stiffness k, and damping c, the steady displacement amplitude is that force divided by √[(k−Mω²)²+(cω)²]. Resonance and damping matter; vibration is not simply proportional to rpm.'},{title:'Water separation',body:'The drum supplies inward force to the retained load. Water can move relative to the fabric and pass through holes. No outward force is needed in an inertial-frame description; a rotating-frame explanation may introduce centrifugal force explicitly.'}],
 misconception:'Fast spinning does not create water or make the drum suck it out. Water must separate from the fabric, pass through the drum, collect in the tub, and reach the drain.',
 limits:'Stages are manually selected. Clothing is represented by ideal markers with prescribed capture at a lifter and ballistic free flight, not deformable fabric. Water chemistry, fluid flow, heating, motor control, transients, and load redistribution are omitted. Vibration assumes a 40 kg assembly, 18 kN/m stiffness, 1200 N·s/m damping, and 25 cm load radius; motion is visibly slowed and enlarged.',
 sources:[{title:'OpenStax: centripetal force',url:'https://openstax.org/books/university-physics-volume-1/pages/6-3-centripetal-force'},{title:'OpenStax: forced oscillations',url:'https://openstax.org/books/university-physics-volume-1/pages/15-6-forced-oscillations'}],
 quiz:{question:'What happens to the required inward acceleration if spin speed doubles at fixed radius?',options:['It quadruples.','It doubles.','It becomes zero.'],answer:0,explanation:'Inward acceleration is ω²R, so it grows with the square of angular speed.'}
};

